pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address adr, bytes memory data, address sender, uint256 msgValue) public {
        vm.assume(sender != c.Owner());
        (bool ok,) = address(adr).call{value: 0}("");
        vm.assume(ok);
        vm.deal(sender, msgValue);
        vm.prank(sender);
        bool succeeded;
        try c.Command(adr, data) {
            succeeded = true;
        } catch {
            succeeded = false;
        }
        assertTrue(succeeded == false);
    }
}
